import csv
from decimal import Decimal
from pathlib import Path


def answer() -> int:
    data_dir = Path('/app/dataset')

    def read_csv(filename):
        with (data_dir / filename).open(newline='', encoding='utf-8') as f:
            return list(csv.DictReader(f))

    def number(value):
        return Decimal(value.replace(',', '.'))

    catalog = read_csv('product_catalog.csv')
    by_product_id = {p['product_id']: p for p in catalog}
    by_ean = {p['ean_code']: p for p in catalog}
    temperatures = {
        (r['timestamp'], r['zone'].strip().lower()): number(r['temperature_c'])
        for r in read_csv('temperature_logs.csv')
    }

    # The exceptional overnight batch contains eight meat/frozen dispatches.
    # Both sensor readings bracketing it exceed their safe temperatures.
    disposal_time = '2023-07-18 03:17:00'
    disposal_ids = set(range(127, 135))
    total = Decimal(0)
    disposal_value = Decimal(0)
    observed_disposal_ids = set()

    for dispatch in read_csv('warehouse_dispatches.csv'):
        if not '2023-07-01' <= dispatch['timestamp'] < '2023-08-01':
            continue

        # Dispatch 169 uses the kettle's EAN barcode as its product identifier.
        identifier = dispatch['product_id']
        product = by_product_id.get(identifier) or by_ean[identifier]
        value = int(dispatch['quantity']) * number(product['unit_price'])
        dispatch_id = int(dispatch['dispatch_id'])

        if dispatch_id in disposal_ids:
            assert dispatch['timestamp'] == disposal_time
            zone = product['storage_category'].strip().lower()
            assert zone in {'meat', 'frozen'}
            safe_temperature = number(product['max_safe_temp_c'])
            for timestamp in ('2023-07-18 02:00:00', '2023-07-18 04:00:00'):
                assert temperatures[timestamp, zone] > safe_temperature
            observed_disposal_ids.add(dispatch_id)
            disposal_value += value
        else:
            # Each unique dispatch ID is retained, including matching details.
            total += value

    assert observed_disposal_ids == disposal_ids
    assert disposal_value == Decimal('10000')
    assert total == total.to_integral_value()
    return int(total)


if __name__ == '__main__':
    import json

    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)

